# Create simple diamond around each box

def make_simple_diamond_center(center_row, center_col, diameter=5):
    """Create a diamond pattern centered at (center_row, center_col)"""
    result = []
    half = diameter // 2

    for r in range(center_row - half, center_row + half + 1):
        dist = abs(r - center_row)
        max_offset = half - dist
        for c in range(center_col - max_offset, center_col + max_offset + 1):
            result.append((r, c))

    return set(result)

