def make_plus_shape(center_r, center_c):
    """Create a + (plus) shape"""
    result = {(center_r, center_c)}
    if center_r > 0: result.add((center_r - 1, center_c))
    if center_r < len(grid) - 1: result.add((center_r + 1, center_c))
