def make_small_diamond_at_box_corner(box_center, corner='bottom-right'):
    """Create a small 5-cell diamond adjacent to a box corner"""
    cr, cc = box_center

    # Positions relative to box center
    offsets = {
        'top-left': [(-2, -1), (-1, -2), (-1, -1)],
        'top-right': [(-2, 0), (-1, 1), (-1, 0)],
        'bottom-left': [(1, -2), (2, -1), (1, -1)],
        'bottom-right': [(0, 2), (1, 1), (1, 2)]
    }

    pos_offsets = offsets.get(corner, [])
    result = set()

    for dr, dc in pos_offsets:
        r, c = cr + dr, cc + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            result.add((r, c))

    return result

